story=[];html=[]

def p(t):
    html.append('<p>'+t+'</p>');story.append(Paragraph(t,styles['Ru']))
def h(t):
    html.append('<h2>'+escape(t)+'</h2>');story.append(Paragraph(escape(t),styles['RuH']))
def source(*keys):
    p('Основание: '+'; '.join(f'<a href="{SOURCES[k][1]}">{SOURCES[k][0]}</a>' for k in keys)+'. Проверено 08.10.2026; применимость к конкретной машине и установке уточняется отдельно.')
def table(headers,rows,widths=None):
    html.append('<div class="table"><table><thead><tr>'+''.join('<th>'+escape(str(t))+'</th>' for t in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(str(t))+'</td>' for t in row)+'</tr>' for row in rows)+'</tbody></table></div>')
    cells=[[Paragraph(escape(str(t)),styles['RuCell']) for t in row] for row in [headers]+rows]
    tb=Table(cells,colWidths=widths or [500/len(headers)]*len(headers),repeatRows=1,hAlign='LEFT')
    tb.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#dbeafe')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,-1),.3,colors.HexColor('#cbd5e1')),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]))
    story.extend([tb,Spacer(1,10)])
def f(x,n=1):return format(Decimal(str(x)).quantize(Decimal(10)**-n,rounding=ROUND_HALF_UP),f'.{n}f').replace('.',',')
def row(label,key):return [label]+[f(s['rated'][key]) for s in S]

